// Run Once for All Items — receives all paginated pages
const pages = $input.all();
const client = $('Split in Batches').first().json;

// Flatten all campaigns from all pages
const allCampaigns = [];
for (const page of pages) {
  const items = page.json?.data;
  if (Array.isArray(items)) allCampaigns.push(...items);
}

if (allCampaigns.length === 0) {
  return [{ json: { sql: 'SELECT 1', count: 0, client_name: client.name } }];
}

const typeMap = {
  'outbound':      'outreach',
  'reply_followup': 'nurture',
};
// The OOO follow-up campaigns, matched by NAME because the vendor's own `type` does not identify
// them and never has. Neither branch of typeMap can produce 'ooo_followup', so before this every
// OOO campaign was ingested misclassified: 'reply_followup' landed as 'nurture' (invisible to the
// OOO routing editor, which requires type='ooo_followup'), and anything else fell through to
// 'outreach' -- which is the one type clients can see (ADR-0003). That is not hypothetical: 25 of
// them were typed 'outreach' and 9 clients could see their own OOO follow-ups, stats included,
// until 20260722g reclassified 52 rows by hand.
//
// The list is measured, not guessed: these are the 7 distinct names carrying an OOO campaign in
// production as of 2026-08-12, and on that data the rule is exact both ways -- 52 of 52 rows whose
// name mentions OOO are ooo_followup, and no ooo_followup row has a name that does not.
// The 'OOO campaign automation' spelling is the older one 20260722g could only catch by id.
const OOO_CAMPAIGN_NAMES = new Set([
  'OOO automation | general',
  'OOO automation | male',
  'OOO automation | female',
  'OOO campaign automation | general',
  'OOO campaign automation | male',
  'OOO campaign automation | female',
  'OOO campaign automation',
]);
const statusMap = {
  'active':    'active',
  'launching': 'launching',
  'draft':     'draft',
  'paused':    'stopped',
  'failed':    'stopped',
  'archived':  'completed',
  'completed': 'completed',
};

const safe = s => (s || '').replace(/'/g, "''");

const values = allCampaigns.map(c => {
  // Name first: it is the only signal that reliably separates an OOO follow-up from outreach.
  // This is INSERT-only in effect -- `type` is deliberately absent from the ON CONFLICT list below,
  // so an existing row keeps its classification and this cannot overwrite 20260722g's work or the
  // type bison-workspace-setup seeds when it provisions a campaign. Nothing needs a backfill:
  // measured 2026-08-12, zero OOO campaigns are currently misclassified.
  const type   = OOO_CAMPAIGN_NAMES.has(String(c.name || '').trim())
    ? 'ooo_followup'
    : (typeMap[c.type] || 'outreach');
  const status = statusMap[c.status] || 'draft';
  const name   = safe(c.name);
  const dbSize = Number(c.total_leads)  || 0;
  const posRes = Number(c.interested)   || 0;
  const startDate = c.created_at ? `'${c.created_at.substring(0, 10)}'` : 'NULL';
  return `('${client.id}', '${c.id}', '${type}'::campaign_type, '${name}', '${status}'::campaign_status, ${dbSize}, ${posRes}, ${startDate})`;
}).join(',\n');

const sql = `
INSERT INTO campaigns
  (client_id, external_id, type, name, status, database_size, positive_responses, start_date)
VALUES
${values}
ON CONFLICT (external_id) DO UPDATE SET
  name               = EXCLUDED.name,
  status             = EXCLUDED.status,
  database_size      = EXCLUDED.database_size,
  positive_responses = EXCLUDED.positive_responses,
  updated_at         = NOW()
RETURNING external_id, name, status
`;

return [{ json: { sql, count: allCampaigns.length, client_name: client.name } }];
